// 1. Haal de beschikbare topics op uit de 'Get Ideas' node
const availableRecords = $('Get Post Ideas').all();
const availableTopics = availableRecords.map(item => {
  return item.json.Topic || item.json.topic || (item.json.fields ? item.json.fields.Topic : undefined);
}).filter(t => t !== undefined);

// 2. Haal de LAATSTE 14 posts op uit de 'Check History Posts' node
const historyRecords = $('Check History Posts').all();
const recentTopics = historyRecords.map(item => {
  return item.json.Topic || item.json.topic || (item.json.fields ? item.json.fields.Topic : undefined);
}).filter(t => t !== undefined);

// 3. Filter: Hou alleen de onderwerpen over die NIET in de afgelopen 14 dagen zijn gepost
const freshTopics = availableTopics.filter(topic => !recentTopics.includes(topic));

// 4. Als ALLE beschikbare opties in de afgelopen 14 dagen al zijn gebruikt
if (freshTopics.length === 0) {
  return [{
    json: {
      topic: "Alle beschikbare topics zijn de afgelopen 14 dagen al gepost!",
      isValid: false
    }
  }];
}

// 5. Kies een willekeurig onderwerp uit de "toegestane" lijst
const chosenTopic = freshTopics[Math.floor(Math.random() * freshTopics.length)];

return [{
  json: {
    topic: chosenTopic,
    isValid: true
  }
}];
